#include "fx_rom.h"
#include "fx_tex.h"
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <map>

#include "fx_romdata.inc"   // generated by tools_pc/fxview/CMakeLists.txt: kImageListU, kSegU, kOffU[9]

static std::vector<uint8_t> g_rom;
static std::map<std::string, std::vector<ImgEntry>> g_tables;
static std::string g_note = "no ROM";
static const char* const kTableNames[9] = { "impactimages", "explosion_smokeimages", "scattered_explosions", "flareimage1", "flareimage2",
                                            "flareimage3", "flareimage4", "flareimage5", "ammo9mmimage" };   // segment order (src/game/image_bank.c)

static bool readAll(const std::string& p, std::vector<uint8_t>& out) {
    FILE* f = fopen(p.c_str(), "rb");
    if (!f) return false;
    fseek(f, 0, SEEK_END);
    const long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n <= 0) { fclose(f); return false; }
    out.resize((size_t)n);
    const bool ok = fread(out.data(), 1, out.size(), f) == out.size();
    fclose(f);
    return ok;
}

static bool exists(const std::string& p) {
    FILE* f = fopen(p.c_str(), "rb");
    if (f) fclose(f);
    return f != nullptr;
}

std::string fxRomFind(const std::string& arg) {
    if (!arg.empty()) return exists(arg) ? arg : std::string();
    for (const char* key : { "FXVIEW_ROM", "N64_ROM" }) {
        const char* e = getenv(key);
        if (e && *e && exists(e)) return e;
    }
#ifdef __SWITCH__
    const char* dirs[] = { "sdmc:/switch/project-dam/data" };
#else
    const char* dirs[] = { "data", "../data", "." };
#endif
    for (const char* d : dirs) {
        for (const char* n : { "ge007.ntsc-final.z64", "baserom.u.z64" }) {
            const std::string p = std::string(d) + "/" + n;
            if (exists(p)) return p;
        }
        if (DIR* dir = opendir(d)) {
            std::string hit;
            while (dirent* de = readdir(dir)) {
                const size_t n = strlen(de->d_name);
                if (n > 4 && strcmp(de->d_name + n - 4, ".z64") == 0) { hit = std::string(d) + "/" + de->d_name; break; }
            }
            closedir(dir);
            if (!hit.empty()) return hit;
        }
    }
    return std::string();
}

bool fxRomOpen(const std::string& path, const std::string& workDir) {
    g_rom.clear();
    g_tables.clear();
    if (!readAll(path, g_rom) || g_rom.size() < 0x400000) { g_note = "cannot read the ROM " + path; g_rom.clear(); return false; }
    if (g_rom[0x3E] != 'E') { g_note = "not the US ROM (a big-endian ntsc .z64 is expected; the image list is the US one)"; g_rom.clear(); return false; }
    const size_t base = (size_t)(kSegU & 0x0FFFFFFF);   // cartridge address 0x10xxxxxx -> ROM file offset
    for (int i = 0; i + 1 < 9; i++) {
        const unsigned a = kOffU[i], b = kOffU[i + 1];
        std::vector<ImgEntry> t;
        for (unsigned o = a; o + 12 <= b; o += 12) {
            const uint8_t* e = &g_rom[base + o];
            ImgEntry x;
            x.index = ((uint32_t)e[0] << 24) | ((uint32_t)e[1] << 16) | ((uint32_t)e[2] << 8) | e[3];
            x.w = e[4]; x.h = e[5]; x.level = e[6]; x.format = e[7]; x.depth = e[8]; x.flagsS = e[9]; x.flagsT = e[10];
            t.push_back(x);
        }
        g_tables[kTableNames[i]] = t;
    }
    {   // skywaterimages: the sky mode's water textures (src/game/sky.c), its entries up to the next table
        std::vector<ImgEntry> t;
        for (unsigned o = kSkyWaterU[0]; o + 12 <= kSkyWaterU[1]; o += 12) {
            const uint8_t* e = &g_rom[base + o];
            ImgEntry x;
            x.index = ((uint32_t)e[0] << 24) | ((uint32_t)e[1] << 16) | ((uint32_t)e[2] << 8) | e[3];
            x.w = e[4]; x.h = e[5]; x.level = e[6]; x.format = e[7]; x.depth = e[8]; x.flagsS = e[9]; x.flagsT = e[10];
            t.push_back(x);
        }
        g_tables["skywaterimages"] = t;
    }
    const std::string list = workDir + "imagelist.u.csv";   // offsets only
    FILE* f = fopen(list.c_str(), "wb");
    if (!f) { g_note = "cannot write " + list; return false; }
    fwrite(kImageListU, 1, sizeof kImageListU - 1, f);
    fclose(f);
    if (!mv_tex_set_imagelist(list) || !fx_tex_set_imagelist(list)) { g_note = "bad image list"; return false; }
    char b[160];
    snprintf(b, sizeof b, "ROM ok (US, image table at 0x%X)", (unsigned)base);
    g_note = b;
    return true;
}

bool fxRomLoaded() { return !g_rom.empty(); }
const std::string& fxRomNote() { return g_note; }
const ImgEntry* fxTableEntry(const char* table, int i) {
    auto it = g_tables.find(table);
    if (it == g_tables.end() || i < 0 || i >= (int)it->second.size()) return nullptr;
    return &it->second[(size_t)i];
}
int fxTableCount(const char* table) {
    auto it = g_tables.find(table);
    return it == g_tables.end() ? 0 : (int)it->second.size();
}
bool fxRomTexture(int texnum, MvTexImage& out) {
    if (g_rom.empty()) { out = MvTexImage(); out.note = "no ROM"; return false; }
    return fx_tex_load(g_rom.data(), g_rom.size(), texnum, out);
}

// ---------------------------------------------------------------- texture names (images.def)
static const char* const kHitKeys[13] = { "HIT_DEFAULT", "HIT_STONE", "HIT_WOOD", "HIT_METAL", "HIT_GLASS", "HIT_WATER", "HIT_SNOW", "HIT_DIRT", "HIT_MUD", "HIT_TILE", "HIT_METALOBJ", "HIT_CHR", "HIT_GLASS_XLU" };
const char* fxHitName(int hit) { return hit >= 0 && hit < 13 ? kHitKeys[hit] : "?"; }
const std::vector<FxTexName>& fxTexNames() {
    static std::vector<FxTexName> v;
    if (!v.empty()) return v;
    const char* p = kTexNames;
    while (*p) {
        const char* e = strchr(p, '\n');
        if (!e) e = p + strlen(p);
        const std::string line(p, (size_t)(e - p));
        const size_t c = line.rfind(',');
        if (c != std::string::npos) {
            FxTexName t;
            t.name = line.substr(0, c);
            const std::string h = line.substr(c + 1);
            t.hit = 0;
            for (int i = 0; i < 13; i++) if (h == kHitKeys[i]) t.hit = i;
            v.push_back(t);
        }
        p = *e ? e + 1 : e;
    }
    return v;
}

// ---------------------------------------------------------------- the guards' weapons' GUNFIRE nodes (model.c, opcode 12)
static std::vector<FxGun> g_guns;
static bool g_gunsScanned = false;
static std::string g_gunNote;
static float rdF(const uint8_t* p) { uint32_t u = ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; float f; memcpy(&f, &u, 4); return f; }
static uint32_t rdU(const uint8_t* p) { return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; }
const std::string& fxGunNote() { return g_gunNote; }
const std::vector<FxGun>& fxGuns() {
    if (g_gunsScanned) return g_guns;
    g_gunsScanned = true;
    if (g_rom.empty()) { g_gunNote = "no ROM"; return g_guns; }
    const std::string csv = kFileListU;
    size_t p = 0;
    while (p < csv.size()) {
        size_t e = csv.find('\n', p);
        if (e == std::string::npos) e = csv.size();
        const std::string line = csv.substr(p, e - p);
        p = e + 1;
        const size_t c1 = line.find(','), c2 = c1 == std::string::npos ? c1 : line.find(',', c1 + 1);
        if (c2 == std::string::npos) continue;
        const std::string path = line.substr(c2 + 1, line.find(',', c2 + 1) - c2 - 1);
        const size_t sl = path.find_last_of('/');
        std::string name = path.substr(sl == std::string::npos ? 0 : sl + 1);
        if (name.size() > 4 && name.compare(name.size() - 4, 4, ".bin") == 0) name.resize(name.size() - 4);
        if (name.compare(0, 4, "Pchr") != 0) continue;
        const size_t a = (size_t)strtoull(line.c_str(), nullptr, 10), n = (size_t)strtoull(line.c_str() + c1 + 1, nullptr, 10);
        if (a + n > g_rom.size() || n < 4) continue;
        std::vector<uint8_t> d;
        if (!mv_inflate_raw(&g_rom[a + 2], n - 2, d)) continue;   // the 1172 header, then raw deflate
        const size_t D = d.size();
        for (size_t o = 0; o + 0x18 <= D; o += 4) {   // a node: u16 opcode, pad, then the record (segment 5 = the file)
            if (d[o] != 0 || d[o + 1] != 12 || d[o + 2] || d[o + 3]) continue;
            const uint32_t r = rdU(&d[o + 4]);
            if (r >> 24 != 5 || (r & 0xFFFFFF) + 0x28 > D) continue;
            const uint8_t* R = &d[r & 0xFFFFFF];
            FxGun g;
            g.name = name.substr(4, name.size() - 5);
            for (int k = 0; k < 3; k++) { g.off[k] = rdF(R + 4 * k); g.size[k] = rdF(R + 12 + 4 * k); }
            const uint32_t img = rdU(R + 0x18);
            if (img >> 24 == 5 && (img & 0xFFFFFF) + 12 <= D) { const uint8_t* T = &d[img & 0xFFFFFF]; g.tex = rdU(T); g.w = T[4]; g.h = T[5]; g.fs = T[9]; g.ft = T[10]; }
            bool ok = g.size[0] > 0 && g.tex > 0;
            for (int k = 0; k < 3; k++) ok = ok && fabsf(g.off[k]) < 1e4f && fabsf(g.size[k]) < 1e4f;
            if (ok) { g_guns.push_back(g); break; }
        }
    }
    char b[96];
    snprintf(b, sizeof b, "%d guards' weapons with a GUNFIRE node", (int)g_guns.size());
    g_gunNote = b;
    return g_guns;
}
